{"explanation":"The tangent function repeats every \(\pi\) and grows without bound near certain x-values. Its vertical asymptotes occur where \(\cos x=0\): \(x=\frac{\pi}{2}+k\pi\), shown here as dashed red lines. Use the checkbox to toggle those asymptotes.","manimCode":"const ax = new Axes({
  xRange: [-2 * Math.PI, 2 * Math.PI, Math.PI / 2],
  yRange: [-4, 4, 1],
  xLength: 11.5,
  yLength: 5.6,
  tips: true
});

const heading = new MathTex({ latex: 'y=\\tan(x)' });
await heading.waitForRender();
heading.moveTo([0, 3.25, 0]);

const note = new Text({
  text: 'Vertical asymptotes:  x = π/2 + kπ',
  color: RED_B,
  fontSize: 22
});
note.moveTo([0, -3.25, 0]);

const gap = 0.25;
const bounds = [
  [-2 * Math.PI, -3 * Math.PI / 2 - gap],
  [-3 * Math.PI / 2 + gap, -Math.PI / 2 - gap],
  [-Math.PI / 2 + gap, Math.PI / 2 - gap],
  [Math.PI / 2 + gap, 3 * Math.PI / 2 - gap],
  [3 * Math.PI / 2 + gap, 2 * Math.PI]
];
const curves = bounds.map(([a, b]) => ax.plot(x => Math.tan(x), {
  xRange: [a, b],
  color: BLUE_B,
  strokeWidth: 3,
  numSamples: 350
}));

const asymptoteXs = [-3 * Math.PI / 2, -Math.PI / 2, Math.PI / 2, 3 * Math.PI / 2];
const asymptotes = asymptoteXs.map(x => {
  const line = new Polygon({
    vertices: [ax.c2p(x, -4), ax.c2p(x, 4)],
    color: RED
  });
  line.setStrokeWidth(2).setFillOpacity(0).setOpacity(0.75);
  return line;
});

scene.add(ax, heading, note, ...curves, ...asymptotes);

const controls = new Controls(scene, { position: 'top-right', theme: 'dark', width: 220 });
controls.addCheckbox({
  label: 'Show asymptotes',
  checked: true,
  onChange: checked => {
    if (checked) scene.add(...asymptotes);
    else scene.remove(...asymptotes);
  }
});

await scene.wait(999999);"}

